        ask_superseded = int(sd("alpha", "leader", "CLOSED-BY-SUPERSESSION: ignore me", type="ask")
                             .split("#")[1].split()[0])
        sd("alpha", "leader", "withdrawn", type="note", supersedes=ask_superseded)
