        def section_of(text, title):
            lines = text.splitlines()
            start = next((i for i, ln in enumerate(lines) if ln.startswith(title)), None)
            if start is None:
                return ""
            body = []
            for ln in lines[start + 1:]:
                if not ln.startswith("  "):
                    break
                body.append(ln)
            return "\n".join(body)

        out = run(cmd_pending, agent="leader")
