        probe = {"cur": 0, "max": 0}
        plock = threading.Lock()

        def recording_wake(pane, text):
            with plock:
                probe["cur"] += 1
                probe["max"] = max(probe["max"], probe["cur"])
            time.sleep(0.05)
            with plock:
                probe["cur"] -= 1
            return True, ""

        saved_wake = wake
        wake = recording_wake
